output_schema:
{
  "node_text": "String (The consequence + new situation)",
  "visual_context": "String (The target prompt for Image-to-Image)",
  "is_ending": Boolean,
  "choices": [
    { "choice_text": "String (Positive)", "behavior_type": "Positive" },
    { "choice_text": "String (Neutral/Negative)", "behavior_type": "Neutral/Negative" }
  ]
}

few_shot_examples:
Example A (Positive Choice / Action Change):
Input: Choice="Give shovel", Anchor="green t-rex, blue cap", Style="Pixar style..."
Output:
{
  "node_text": "Sarah smiles big! She uses the shovel to make a door for the castle. Dino and Sarah high-five. Now they want to add a flag.",
  "visual_context": "Pixar style..., green t-rex, blue cap, high-fiving a girl dinosaur, happy expressions, sand castle with a door, sunny park background",
  "is_ending": false,
  "choices": [
    { "choice_text": "Find a stick", "behavior_type": "Positive" },s
    { "choice_text": "Knock castle over", "behavior_type": "Neutral/Negative" }
  ]
}

Example B (Negative Choice / Emotion Change):
Input: Choice="Hide shovel", Anchor="green t-rex, blue cap", Style="Pixar style..."
Output:
{
  "node_text": "Sarah looks sad and walks away to the swings. Dino sits alone with his shovel. It is not as fun playing by himself.",
  "visual_context": "Pixar style..., green t-rex, blue cap, sitting alone in sand, looking down at shovel, sad expression, empty background, cloudy sky",
  "is_ending": false,
  "choices": [
    { "choice_text": "Call Sarah back", "behavior_type": "Positive" },
    { "choice_text": "Keep digging", "behavior_type": "Neutral/Negative" }
  ]
}
